sub with_refresh_lock {
    my ($callback) = @_;
    my $state_dir = session_state_dir();
    return $callback->() if !defined $state_dir;

    my $lock_path = "${state_dir}/output-refresh.lock";
    open my $lock_fh, '>>', $lock_path or return $callback->();
    flock($lock_fh, LOCK_EX) or return $callback->();
    my $result = $callback->();
    close $lock_fh;
    return $result;
}

sub session_state_dir {
    my $base = $ENV{XDG_STATE_HOME} // q{};
    if ($base eq q{}) {
        my $home = $ENV{HOME} // q{};
        $base = $home ne q{} ? "${home}/.local/state" : "/tmp/labwc-$<";
    }

    my $dir = "${base}/labwc";
    eval {
        make_path($dir, { mode => 0700 }) if !-d $dir;
        1;
    } or return undef;
    return $dir;
}

sub topology_state_dir {
    my $base = $ENV{XDG_RUNTIME_DIR} // q{};
    if ($base eq q{}) {
        return session_state_dir();
    }

    my $dir = "${base}/labwc";
    eval {
        make_path($dir, { mode => 0700 }) if !-d $dir;
        1;
    } or return undef;
    return $dir;
}

sub topology_state_path {
    my $dir = topology_state_dir();
    return undef if !defined $dir;
    return "${dir}/output-topology.state";
}

sub load_saved_topology {
    my $path = topology_state_path();
    return q{} if !defined $path || !-r $path;

    open my $fh, '<', $path or return q{};
    local $/ = undef;
    my $state = <$fh> // q{};

sub session_is_wayland_active {
    return 1 if defined $ENV{WAYLAND_DISPLAY} && $ENV{WAYLAND_DISPLAY} ne q{};
    return 1 if defined $ENV{SWAYSOCK} && $ENV{SWAYSOCK} ne q{};
    return (($ENV{XDG_SESSION_TYPE} // q{}) eq 'wayland') ? 1 : 0;
}

sub enabled_setting {
    my ($value) = @_;
    return 1 if !defined $value;
    return $value =~ /\A(?:true|yes|1|on)\z/i ? 1 : 0;
}

sub process_running {
    my ($process_name) = @_;
    return 0 if !process_name_safe($process_name);

    my $pgrep = find_command('pgrep');
    return 0 if !defined $pgrep;

    system {$pgrep} $pgrep, '-U', $<, '-x', $process_name;
    return $? == 0 ? 1 : 0;
}

sub restart_waybar {
    return if !enabled_setting($defaults{LABWC_ENABLE_WAYBAR});

    my $waybar      = find_command('waybar');
    my $systemctl   = find_command('systemctl');
    my $waybar_live = process_running('waybar');
    return if !defined $waybar;

    if (defined $systemctl) {
        system {$systemctl} $systemctl, '--user', '--quiet', 'is-active', 'waybar.service';
        if ($? == 0) {
            system {$systemctl} $systemctl, '--user', '--no-block', 'restart', 'waybar.service';
            return;
        }

        if (!$waybar_live) {
            system {$systemctl} $systemctl, '--user', '--no-block', 'start', 'waybar.service';
            return if $? == 0;
        }
    }

    my $home = $ENV{HOME} // q{};
    return if $home eq q{};

    my $config_path = "${home}/.config/waybar/config";
    my $style_path  = "${home}/.config/waybar/style.css";
    return if !-r $config_path || !-r $style_path;

    if ($waybar_live) {
        my $pkill = find_command('pkill');
        return if !defined $pkill;

        system {$pkill} $pkill, '-u', $<, '-x', 'waybar';
        for (1 .. 20) {
            last if !process_running('waybar');
            usleep(50_000);
        }
        return if process_running('waybar');
    }

    my @command = ($waybar, '-c', $config_path, '-s', $style_path);
    start_detached(@command);
    return;
}

sub stop_fuzzel {
    my $pkill = find_command('pkill');
    return if !defined $pkill || !process_running('fuzzel');

    system {$pkill} $pkill, '-TERM', '-u', $<, '-x', 'fuzzel';
